import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, PointLight, Color } = ctx.THREE;

  const container = new Group();

  // 1. PALETTE & CONFIG
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const inkColor = new Color(colors.ink);
  const paperColor = new Color(colors.paper);
  const accentColor = new Color(colors.accent);
  const surfaceColor = new Color(colors.surface);

  // 2. STAGE/BACKDROP (Engineered Gradient Surface + Subtle Rim)
  // Card Size: 512x320 ratio -> width 2.4, height 1.5
  const cardWidth = 2.4;
  const cardHeight = 1.5;
  const backGeo = new PlaneGeometry(cardWidth, cardHeight);

  // Custom TSL Material for the card surface
  const backMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.2,
    transparent: true
  });

  // TSL Shader logic: diagonal gradient from surface (near black) to ink (dark grey) with local accent bleed
  const customColorNode = () => {
    const coords = uv();
    // Diagonal factor
    const diagonal = coords.x.add(coords.y).mul(0.5);
    // Mix surface to ink
    const baseGrad = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b), vec3(inkColor.r, inkColor.g, inkColor.b), diagonal);
    // Edge accent vignette/glow (soft boundary red signal)
    const edge = smoothstep(0.0, 0.45, coords.y.mul(coords.x));
    const finalCol = mix(baseGrad, vec3(accentColor.r, accentColor.g, accentColor.b), edge.mul(0.08));
    return finalCol;
  };

  backMat.colorNode = customColorNode();
  const backMesh = new Mesh(backGeo, backMat);
  container.add(backMesh);

  // 3. IMAGE LAYER (Isolated Hero Asset)
  let imageMesh = null;
  const imageGeo = new PlaneGeometry(1.2, 1.2);
  const imageMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.0, // Fade in on load
    depthWrite: false
  });

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      imageMat.map = texture;
      imageMat.needsUpdate = true;
      gsap.to(imageMat, { opacity: 0.95, duration: 0.8, ease: 'power2.out' });
    });
  }

  imageMesh = new Mesh(imageGeo, imageMat);
  imageMesh.position.set(0.4, 0.0, 0.02); // Positioned nicely on the right halves
  container.add(imageMesh);

  // 4. TEXT CONTENT
  // Extract text and render using MSDF FontAtlas
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineText = items.find(item => item.role === 'headline' || item.text.includes('Features'))?.text ?? 'Features 1';

  // Render using Lora display-style sizing (scaled to match card geometry nicely)
  const title = ctx.fontAtlas.createText(headlineText, {
    fontSize: 0.14,
    color: colors.paper,
    align: 'left'
  });
  // Anchor to the top-left area
  title.position.set(-1.0, 0.5, 0.04);
  container.add(title);

  // Fine aesthetic accent details (Subtle machined line)
  const lineGeo = new PlaneGeometry(0.5, 0.008);
  const lineMat = new MeshBasicNodeMaterial({ color: accentColor });
  const line = new Mesh(lineGeo, lineMat);
  line.position.set(-0.75, 0.35, 0.04);
  container.add(line);

  // Secondary fine-print status/caption to honor the "Nova Atelier" mono/caption vocabulary
  const statusLabel = ctx.fontAtlas.createText('01 / SPECIFICATION', {
    fontSize: 0.05,
    color: colors.accent,
    align: 'left',
    letterSpacingPx: 1.5
  });
  statusLabel.position.set(-1.0, -0.55, 0.04);
  container.add(statusLabel);

  // 5. LIGHTS
  // Elegant rim light pointing at the card edge to pull it out from dark backdrops
  const localRimLight = new PointLight(accentColor, 0.8, 4.0);
  localRimLight.position.set(-1.5, 1.0, 0.8);
  container.add(localRimLight);

  // 6. ENTRANCE ANIMATION & INTERACTION SETUP
  // Elegant entry sequence following "rise-in" design doctrine
  gsap.fromTo(container.position, 
    { y: container.position.y - 0.2 },
    { y: container.position.y, duration: 0.9, ease: 'power4.out' }
  );

  gsap.fromTo(container.scale,
    { x: 0.95, y: 0.95, z: 0.95 },
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }
  );

  // 7. CLEANUP
  container.userData.cleanup = () => {
    backGeo.dispose();
    backMat.dispose();
    imageGeo.dispose();
    imageMat.dispose();
    lineGeo.dispose();
    lineMat.dispose();
    localRimLight.dispose();
    // Font Atlas structures handle text disposal internally
    gsap.killTweensOf(container.position);
    gsap.killTweensOf(container.scale);
    gsap.killTweensOf(imageMat);
  };

  return container;
}
